static std::mt19937 gen(std::random_device{}());
for (size_t i = 0; i < velocities.size(); ++i) {
    double prob = collisionFreq * dt;
    if (std::uniform_real_distribution<double>(0.0, 1.0)(gen) < prob) {
        double sigma = std::sqrt(targetTemp / masses[i]);
        std::normal_distribution<double> ndist(0.0, sigma);
        velocities[i].x = ndist(gen);
        velocities[i].y = ndist(gen);
        velocities[i].z = ndist(gen);
    }
}

